        'hero_heading' => 'Έργα',
        'hero_sub' => 'Σχεδιάστε και τρέξτε έργα πληροφορικής πάνω στις εργασίες που ήδη έχετε και δείτε με μια ματιά αν το καθένα βαίνει καλά.',
        'overview' => [
            'nav' => 'Τι είναι',
            'title' => 'Τι είναι τα Έργα',
            'intro' => 'Ένα σημείο για τα μεγαλύτερα κομμάτια δουλειάς - αυτά που αποτελούνται από δεκάδες εργασίες.',
            'p1' => 'Μια μετακόμιση γραφείου, μια ανανέωση φορητών ή μια μετάβαση του ταχυδρομείου είναι πολύ μεγάλες για να είναι μία εργασία και πολύ σημαντικές για να ζουν σε ένα υπολογιστικό φύλλο. Ένα έργο συγκεντρώνει τις εργασίες που βρίσκονται πίσω του, τις χωρίζει σε φάσεις και υπολογίζει από αυτές πόσο έχει προχωρήσει και αν αντιμετωπίζει προβλήματα.',
            'p2' => 'Για να το δείτε να λειτουργεί πριν σχεδιάσετε το δικό σας, όποιος μπορεί να ανοίξει το Σύστημα μπορεί να εισαγάγει **Σύστημα - Δεδομένα επίδειξης - Εργασίες και Έργα**: εννέα έργα που καλύπτουν κάθε τρόπο διεξαγωγής και κάθε κατάσταση, με τις εργασίες, τα διαγράμματα και το ιστορικό τους. Εισαγάγετε πρώτα Πάγια, Αλλαγές, Αιτήματα, Συμβάσεις, Γνωσιακή βάση και CMDB και τα έργα συσχετίζονται και με αυτές τις εγγραφές. Η νέα εισαγωγή αντικαθιστά μόνο τα έργα επίδειξης.',
