        'map' => [
            'nav' => 'Πώς συνδέονται',
            'title' => 'Πώς συνδέονται',
            'intro' => 'Κάθε μέρος ενός έργου και τι τροφοδοτεί τι - εξερευνήστε το ή περπατήστε ένα έργο από τον στόχο έως τα οφέλη.',
            'open' => 'Άνοιγμα του χάρτη',
            'open_walk' => 'Περπατήστε ένα έργο',
            'p1' => 'Έχει δική του σελίδα, οπότε ο χάρτης παίρνει όλη την οθόνη - υπάρχει και σύνδεσμος από ένα κενό χαρτοφυλάκιο και από την Εργαλειοθήκη. Επιλέξτε οποιοδήποτε πλαίσιο για να δείτε τι είναι, πού το βρίσκετε και ποιο εργαλείο το ενεργοποιεί· οι γραμμές και οι λίστες δείχνουν τι τροφοδοτεί και τι το τροφοδοτεί. Η επιλογή **Περπατήστε ένα έργο** ακολουθεί μια μετακόμιση γραφείου από τον στόχο έως τα οφέλη της, σε δώδεκα βήματα (τα βέλη του πληκτρολογίου κινούνται κι αυτά μέσα σε αυτήν). Η επιλογή **Δείξε με τι ξεκινά ένα έργο** αχνίζει τα μέρη που ένας τρόπος διεξαγωγής αφήνει εκτός στην αρχή - ένα Απλό έργο ξεκινά με πολύ λίγα και η Εργαλειοθήκη στην Επισκόπησή του προσθέτει τα υπόλοιπα όταν τα χρειαστεί.',
            'noscript' => 'Ο διαδραστικός χάρτης χρειάζεται JavaScript. Κάθε μέρος περιγράφεται επίσης στις ενότητες παρακάτω.',
        ],
        'portfolio' => [
            'nav' => 'Το χαρτοφυλάκιο',
            'title' => 'Το χαρτοφυλάκιο',
            'intro' => 'Κάθε έργο ως κάρτα.',
            'p1' => 'Τα Έργα ανοίγουν στο χαρτοφυλάκιο: μία κάρτα ανά έργο, με το χρώμα και το εικονίδιο που διάλεξε ο υπεύθυνός του. Ο δακτύλιος δείχνει πόση από τη δουλειά έχει ολοκληρωθεί και χρωματίζεται ανάλογα με την πορεία του· από κάτω βρίσκονται η ημερομηνία-στόχος, ποιος το αναλαμβάνει και τι συμβαίνει τώρα.',
            'p2' => 'Οι προβολές στα αριστερά απαντούν στις συνήθεις ερωτήσεις - τι είναι ενεργό, τι αναλαμβάνω εγώ, τι χρειάζεται προσοχή, τι έχει ολοκληρωθεί - και τα πλακίδια στην κορυφή μετρούν ό,τι μετράει σε όλες αυτές. Πατήστε **Νέο** για να ξεκινήσετε ένα έργο.',
            'p3' => 'Κάτω από τα πλακίδια, μια γραμμή δείχνει πώς βρίσκονται τα ενεργά έργα - εντός πλάνου, σε κίνδυνο, εκτός πλάνου ή χωρίς ακόμη πορεία - με το πλήθος για το καθένα. Η **Ταξινόμηση** διατάσσει τις κάρτες κατά ημερομηνία-στόχο, προτεραιότητα, πορεία ή όνομα (στο Έργα - Ρυθμίσεις - Γενικά ορίζεται η αρχική σειρά) και ο **Χάρτης πορείας** αντικαθιστά τις κάρτες με μία γραμμή ανά έργο πάνω στο ημερολόγιο: από την έναρξη έως την ημερομηνία-στόχο λήξης, πιο σκούρα για τη δουλειά που έχει γίνει, με το επόμενο ορόσημό του. Κάθε έργο έχει μια **προτεραιότητα** - Χαμηλή, Μεσαία, Υψηλή ή Κρίσιμη, ή τις δικές σας τέσσερις λέξεις από τις ρυθμίσεις - που εμφανίζεται στην κάρτα του όταν δεν είναι Μεσαία.',
            'p4' => 'Τα **Διαγράμματα** (δίπλα στις Κάρτες και τον Χάρτη πορείας) σχεδιάζουν μαζί τα έργα της προβολής: πρόοδο ανά έργο, προϋπολογισμό έναντι πραγματικού (ένα διάγραμμα ανά νόμισμα, με σημείωση για υπέρβαση), θερμικό χάρτη κινδύνων με κάθε ανοιχτό κίνδυνο - επιλέξτε ένα τετράγωνο για να τους δείτε σε λίστα - και κάθε ορόσημο όλων των έργων, που έχει επιτευχθεί, χαθεί ή πλησιάζει. Κάθε διάγραμμα έχει έναν **Πίνακα**.',
            'p5' => 'Η **Εξαγωγή** κατεβάζει τα έργα της προβολής - μετά την προβολή, την αναζήτηση και τη σειρά που επιλέξατε - ως βιβλίο Excel ή αρχείο CSV: κατάσταση, προτεραιότητα, πορεία, πρόοδο, τον υπεύθυνο έργου, ημερομηνίες, εργασίες, ορόσημα και τον προϋπολογισμό στο νόμισμα κάθε έργου. Μια προβολή χωρίς έργα δεν εξάγει τίποτα.',
        ],
        'project' => [
            'nav' => 'Ένα έργο',
            'title' => 'Η σελίδα ενός έργου',
            'intro' => 'Το banner και μετά Επισκόπηση, Πλάνο, Χρονοδιάγραμμα, τα εργαλεία του έργου, Έγγραφα, Αναφορές, Συνδέσεις και Ιστορικό.',
            'p1' => 'Το banner δείχνει το όνομα του έργου, τον στόχο του (πώς είναι το ολοκληρωμένο), την κατάστασή του, πώς διεξάγεται, ποιος το αναλαμβάνει, τις ημερομηνίες του και τον δακτύλιο πορείας. Η **Επεξεργασία** αλλάζει οτιδήποτε από αυτά, και την κατάσταση: αν ένα έργο οριστεί σε Κλειστό, συμπληρώνεται η σημερινή ημέρα ως πραγματική λήξη αν δεν την έχει ορίσει κανείς.',
            'p2' => 'Η Επισκόπηση συγκεντρώνει τους αριθμούς, την **Πρόοδο στον χρόνο** (ένα burn-up: κάθε εργασία του πλάνου έναντι όσων έχουν ολοκληρωθεί, ανά ημέρα ή εβδομάδα, με σημειωμένη την ημερομηνία-στόχο λήξης - επιλέξτε μια φάση για να δείτε μόνο αυτή, ή μετρήστε εκτιμώμενες ώρες αντί για εργασίες), τι συμβαίνει τώρα, τι λήγει σύντομα και τις τελευταίες αλλαγές. Μετά το Πλάνο και το Χρονοδιάγραμμα έρχεται μια καρτέλα για κάθε εργαλείο που χρησιμοποιεί το έργο - Άτομα, Πεδίο, RACI, RAID, Πύλες, Προϋπολογισμός, Έλεγχος αλλαγών και Οφέλη, που περιγράφονται παρακάτω - και μετά τα **Έγγραφα** (πλάνα, σχέδια, επιστολές έγκρισης: ένα ανεβασμένο αρχείο ή ένας σύνδεσμος προς το σημείο όπου βρίσκεται), οι Αναφορές και οι Συνδέσεις. Με όλα τα εργαλεία ενεργά, η γραμμή καρτελών κυλά οριζόντια. Το Ιστορικό καταγράφει ό,τι έχει αλλάξει και ποιος το άλλαξε.',
            'p3' => 'Κάτω από την **Πρόοδο στον χρόνο** (burn-up, ή **Burndown** - τι απομένει έναντι μιας ιδανικής γραμμής έως το τέλος) η Επισκόπηση έχει την **Κατάσταση εργασιών** (μια γραμμή ανά στάδιο: πόσες εργασίες βρίσκονται σε κάθε κατάσταση εργασιών σας, με πόσες είναι καθυστερημένες ή περιμένουν άλλη εργασία), την **Πρόοδο ανά στάδιο** και τη **Ροή στον χρόνο** - το αθροιστικό διάγραμμα ροής: εργασίες σε κάθε κατάσταση, ημέρα με την ημέρα. Μια ζώνη που συνεχίζει να πλαταίνει είναι δουλειά που συσσωρεύεται εκεί. Οι καταστάσεις καταγράφονται μία φορά την ημέρα από την έκδοση 3.3.0· πριν από αυτήν είναι γνωστό μόνο πότε δημιουργήθηκαν και ολοκληρώθηκαν οι εργασίες, και εμφανίζεται με γκρι.',
            'p4' => 'Πάνω από τα διαγράμματα, η Επισκόπηση λέει τι χρειάζεται κάποιον, μόνο όταν ισχύει: ένα ορόσημο που χάθηκε, μια εξάρτηση ή απόφαση που πέρασε την ημερομηνία της, ανασκοπήσεις οφελών που λήγουν, αιτήματα αλλαγής που περιμένουν απόφαση και ό,τι έχει κλιμακωθεί στο αρχείο RAID - το καθένα με **Εμφάνιση όλων**. Ύστερα το πλαίσιο **Πρόταση** σε ένα έργο που προτάθηκε (Έγκριση και Απόρριψη όσο περιμένει), η **Εργαλειοθήκη** (δείτε Εργαλεία) και η **Ενημέρωση** AI.',
        ],
        'plan' => [
            'nav' => 'Το πλάνο',
            'title' => 'Χτίζοντας το πλάνο',
            'intro' => 'Πρώτα οι φάσεις, μετά οι εργασίες.',
            'p1' => 'Η καρτέλα Πλάνο δείχνει κάθε φάση (ή στάδιο, ή sprint) ως λωρίδα εργασιών, με τις ημερομηνίες της, την κατάστασή της και πόσες από τις εργασίες της έχουν ολοκληρωθεί. Οι εργασίες που δεν ανήκουν ακόμη σε φάση βρίσκονται στο κάτω μέρος.',
            'p2' => 'Προσθέστε μια εργασία πληκτρολογώντας την στο πλαίσιο κάτω από μια λωρίδα - διαλέξτε ποιος την κάνει και πότε λήγει, αν θέλετε. Σύρετε μια εργασία σε άλλη λωρίδα για να τη μετακινήσετε, ή πάνω και κάτω μέσα στη λωρίδα της για να βάλετε τη λωρίδα σε σειρά - μια γραμμή δείχνει πού θα προσγειωθεί. Από το πληκτρολόγιο, εστιάστε στη λαβή μιας εργασίας και πατήστε το πάνω ή το κάτω βέλος· σε κινητό, το κουμπί μετακίνησης σε κάθε εργασία έχει Πάνω και Κάτω. Πατήστε μια εργασία για να την ανοίξετε στον πίνακα Εργασιών, όπου επεξεργάζεται όπως κάθε άλλη εργασία.',
            'p3' => 'Πατήστε **Έναρξη** σε μια φάση όταν αρχίζει η δουλειά της και **Ολοκλήρωση** όταν τελειώσει. Ο σταυρός στο τέλος της γραμμής μιας εργασίας την αφαιρεί από το έργο· η ίδια η εργασία διατηρείται.',
            'p4' => 'Τα ορόσημα είναι οι ημερομηνίες που υπόσχεται το έργο - η ημέρα μετακόμισης, η έναρξη λειτουργίας, η έγκριση από το διοικητικό συμβούλιο. Πατήστε **Ορόσημο** στην καρτέλα Πλάνο για να προσθέσετε ένα, σε μια φάση ή για ολόκληρο το έργο. Κάθε φάση δείχνει τα ορόσημά της ως ρόμβους· τσεκάρετε το **Επιτεύχθηκε** όταν συμβεί. Ένα ορόσημο του οποίου η ημερομηνία περνά χωρίς να επιτευχθεί θεωρείται χαμένο και κάνει το έργο πορτοκαλί.',
            'step1' => 'Πατήστε **Νέο** στο χαρτοφυλάκιο, δώστε στο έργο ένα όνομα και έναν στόχο και επιλέξτε πώς το τρέχετε.',
            'step2' => 'Στην καρτέλα Πλάνο, προσθέστε τις φάσεις στις οποίες χωρίζεται η δουλειά.',
            'step3' => 'Προσθέστε τις εργασίες κάτω από κάθε φάση, με το ποιος τις κάνει και πότε.',
            'step4' => 'Ξεκινήστε την πρώτη φάση. Από εκεί και πέρα ο δακτύλιος και η πορεία ενημερώνονται μόνα τους.',
        ],
        'timeline' => [
            'nav' => 'Χρονοδιάγραμμα',
            'title' => 'Το Χρονοδιάγραμμα',
            'intro' => 'Ολόκληρο το πλάνο πάνω στο ημερολόγιο.',
            'p1' => 'Η καρτέλα Χρονοδιάγραμμα σχεδιάζει το πλάνο ως διάγραμμα Gantt: κάθε φάση, στάδιο ή sprint είναι μια ζώνη κατά μήκος των ημερομηνιών της, οι εργασίες της είναι γραμμές από την έναρξη έως την προθεσμία τους και τα ορόσημα είναι ρόμβοι - πράσινοι όταν επιτευχθούν, κόκκινοι όταν χαθούν. Μια γραμμή δείχνει το σήμερα και μια άλλη την ημερομηνία-στόχο λήξης.',
            'p2' => 'Με ποντίκι, σύρετε μια γραμμή για να μετακινήσετε μια εργασία ή μια φάση, ή σύρετε όποιο άκρο θέλετε για να αλλάξετε πότε αρχίζει ή τελειώνει· σύρετε έναν ρόμβο για να μετακινήσετε ένα ορόσημο. Κάθε μετακίνηση αποθηκεύεται αμέσως και περνά από τους ίδιους κανόνες με την επεξεργασία στο χέρι, οπότε ο πίνακας Εργασιών, το Ημερολόγιο και η πορεία ακολουθούν. Πατήστε μια γραμμή για να την ανοίξετε. Οι εργασίες χωρίς ημερομηνίες δεν σχεδιάζονται· η καρτέλα λέει πόσες είναι.',
            'p3' => 'Επιλέξτε **Ημέρες**, **Εβδομάδες** ή **Μήνες** για μεγέθυνση. Σε κινητό το διάγραμμα κυλά οριζόντια· οι μετακινήσεις γίνονται πατώντας τα στοιχεία και αλλάζοντας τις ημερομηνίες.',
            'p4' => '**Εξαρτήσεις.** Το κουμπί συσχέτισης στη γραμμή μιας εργασίας λέει τι περιμένει: μια εργασία δεν μπορεί να ξεκινήσει μέχρι να ΤΕΛΕΙΩΣΕΙ μια άλλη, προαιρετικά με κενό μερικών ημερών. Βέλη τις ενώνουν στο διάγραμμα - κόκκινα και διακεκομμένα όπου το πλάνο συγκρούεται (ξεκινά πριν λήξει η άλλη). Η **Κρίσιμη διαδρομή** ξεχωρίζει τις εργασίες χωρίς περιθώριο - όποια ημέρα καθυστερήσουν, καθυστερεί και η λήξη - και αχνίζει τις υπόλοιπες. Ένας βρόχος απορρίπτεται. Στο Πλάνο μια εργασία δείχνει **Αναμονή για 1** όσο κάτι που περιμένει είναι ημιτελές και **Σύγκρουση** όταν οι ημερομηνίες της δεν μπορούν να λειτουργήσουν.',
        ],
        'capacity' => [
            'nav' => 'Δυναμικότητα',
            'title' => 'Εκτιμήσεις και δυναμικότητα',
            'intro' => 'Ποιος έχει περιθώριο και ποιος είναι υπερφορτωμένος τις επόμενες εβδομάδες.',
            'p1' => 'Δώστε σε μια εργασία μια **εκτίμηση** - πόσες ώρες πρέπει να πάρει - στο πλαίσιο της γραμμής της στο Πλάνο, ή στο παράθυρο εργασίας στον πίνακα Εργασιών. Κάθε λωρίδα και η Επισκόπηση δείχνουν τότε τον εκτιμώμενο έναντι του καταγεγραμμένου χρόνου και μια γραμμή γίνεται κόκκινη όταν έχει καταγραφεί περισσότερος χρόνος από τον εκτιμώμενο.',
            'p2' => 'Η σελίδα **Δυναμικότητα**, στην κορυφή των Έργων, έχει μια γραμμή για κάθε άτομο με δουλειά σε έργα και μια στήλη για κάθε εβδομάδα. Το φορτίο μιας εβδομάδας είναι η δουλειά του έργου που τους απομένει - η εκτίμηση κάθε εργασίας μείον τον χρόνο που έχει ήδη καταγραφεί, κατανεμημένη στις εργάσιμες ημέρες από την έναρξή της (ή το σήμερα) έως την προθεσμία της - συν οι βάρδιές τους στο πρόγραμμα βαρδιών του γραφείου εξυπηρέτησης, έναντι των ωρών που εργάζονται σε μια εβδομάδα. Το πράσινο έχει περιθώριο, το πορτοκαλί είναι τεντωμένο, το κόκκινο είναι υπερφορτωμένο. Ανοίξτε μια γραμμή για να δείτε τις εργασίες πίσω από αυτήν.',
            'p3' => 'Δίπλα στις εβδομάδες είναι σε πόσα ενεργά έργα έχει ανοιχτή δουλειά κάθε άτομο (επισημαίνεται από τρία και πάνω), τα ανοιχτά αιτήματά του και η δουλειά χωρίς προθεσμία. Οι εργασίες χωρίς εκτίμηση μετριούνται αλλά δεν προστίθενται, οπότε η σελίδα λέει πόσες είναι - η άγνωστη δουλειά είναι κίνδυνος, όχι μηδέν. Το **Έργα - Ρυθμίσεις - Πορεία** ορίζει τις ώρες μιας εβδομάδας (37,5), πότε μια εβδομάδα γίνεται πορτοκαλί (85%), πόσα έργα θεωρούνται αρκετά, ποιες ημέρες είναι εργάσιμες και αν μετρούν οι βάρδιες του προγράμματος (απενεργοποιήστε το για πρόγραμμα μόνο εφημερίας).',
        ],
        'methods' => [
            'nav' => 'Τρόποι εργασίας',
            'title' => 'Απλός, Σταδιακός και Agile',
            'intro' => 'Ένα έργο, τρεις τρόποι να το βλέπετε.',
            'p1' => 'Ο τρόπος που τρέχετε ένα έργο καθορίζει πώς λέγονται τα χρονικά του πλαίσια και πώς συμπεριφέρονται. Από κάτω, κάθε έργο είναι χτισμένο με τον ίδιο τρόπο, και γι\' αυτό είναι ασφαλές να αλλάξετε γνώμη.',
            'p2' => 'Η αλλαγή μεθόδου στα μισά δεν χάνει τίποτα. Οι ολοκληρωμένες φάσεις κρατούν το όνομα με το οποίο έτρεξαν, οι ανοιχτές παίρνουν αυτό της νέας μεθόδου και η αλλαγή καταγράφεται στο ιστορικό του έργου. Αν η νέα μέθοδος επιτρέπει μόνο ένα χρονικό πλαίσιο σε εξέλιξη κάθε φορά, το πρώτο παραμένει σε εξέλιξη και τα υπόλοιπα επιστρέφουν σε προγραμματισμένα.',
            'simple_d' => 'Φάσεις και εργασίες. Οποιοσδήποτε αριθμός φάσεων μπορεί να βρίσκεται σε εξέλιξη ταυτόχρονα.',
            'staged_d' => 'Στάδια που ολοκληρώνετε ένα-ένα πριν ξεκινήσετε το επόμενο, με το στυλ του PRINCE2 - για έργα που αναφέρονται σε διοικητικό συμβούλιο.',
            'agile_d' => 'Sprint, ένα κάθε φορά - για δουλειά που αλλάζει όσο μαθαίνετε.',
