        'tools' => [
            'nav' => 'Εργαλεία',
            'title' => 'Τα εργαλεία ενός έργου και η προσαρμογή τους',
            'intro' => 'Κάθε τρόπος διεξαγωγής ενός έργου ενεργοποιεί το δικό του σύνολο.',
            'p1' => 'Ένα έργο μπορεί να χρησιμοποιεί οκτώ εργαλεία, το καθένα σε δική του καρτέλα: Άτομα, Πεδίο, RACI, RAID, Πύλες, Προϋπολογισμός, Έλεγχος αλλαγών και Οφέλη. Ο τρόπος διεξαγωγής καθορίζει ποια είναι ενεργά στην αρχή:',
            'p2' => 'Για να προσαρμόσετε ένα έργο, κάντε **Επεξεργασία** και τσεκάρετε ή ξετσεκάρετε τα εργαλεία κάτω από το **Εργαλεία** (η ενότητα εμφανίζεται κατά την επεξεργασία, όχι κατά τη δημιουργία). Η απενεργοποίηση ενός εργαλείου απλώς κρύβει την καρτέλα του: τίποτα μέσα του δεν διαγράφεται και η ξανά ενεργοποίηση φέρνει πίσω τα πάντα. Αν αλλάξετε τον τρόπο διεξαγωγής του έργου στο ίδιο παράθυρο, τα εργαλεία επιστρέφουν στο δικό σύνολο της νέας μεθόδου.',
            'p3' => 'Η **Εργαλειοθήκη** στην Επισκόπηση παραθέτει τα εργαλεία που το έργο δεν χρησιμοποιεί ακόμη - σε τι χρησιμεύει το καθένα και πότε θα το θέλατε - ώστε ένα Απλό έργο να αναπτύσσει τα εργαλεία του όσο τα χρειάζεται. Όσα προτείνει το ίδιο το έργο έρχονται πρώτα, με την ένδειξη **Προτείνεται** και τον λόγο: τρία ή περισσότερα στάδια προτείνουν Πύλες, μια ημερομηνία-στόχος που έχει ήδη μετατεθεί προτείνει Έλεγχο αλλαγών, μια εκπρόθεσμη εργασία προτείνει RAID. Το **Προσθήκη** ενεργοποιεί το εργαλείο, όπως ακριβώς η Επεξεργασία (η προσθήκη του RACI προσθέτει και τα Άτομα και το Πεδίο, επειδή ο πίνακας χτίζεται από αυτά). Το **Απόκρυψη** το κρύβει για αυτό το έργο στον browser σας. Την βλέπουν μόνο όσοι μπορούν να αλλάξουν το έργο, και όχι όταν αυτό έχει κλείσει. Το **Έργα - Ρυθμίσεις - Γενικά - Εργαλειοθήκη στην Επισκόπηση** την απενεργοποιεί για όλους.',
        ],
        'people' => [
            'nav' => 'Άτομα',
            'title' => 'Άτομα και ρόλοι',
            'intro' => 'Ποιος συμμετέχει στο έργο και τον ρόλο που παίζει ο καθένας.',
            'p1' => 'Στην καρτέλα Άτομα, το **Προσθήκη ατόμου** βάζει έναν τεχνικό, μια ομάδα ή ένα άτομο από τα Άτομα στο έργο, το καθένα με έναν ρόλο. Σε μια εγκατάσταση με περισσότερες από μία εταιρείες, όποιος προστίθεται πρέπει να ανήκει στην εταιρεία του έργου ή να μπορεί να τη βλέπει: ένας τεχνικός που τη βλέπει, μια ομάδα που δίνει πρόσβαση σε αυτήν (στο Σύστημα - Ομάδες), ένα άτομο από εκείνη την εταιρεία. Το ίδιο ισχύει για τον υπεύθυνο έργου. Η συμμετοχή σε ένα έργο δεν αφήνει ποτέ κάποιον να ξεπεράσει την εταιρεία του, οπότε όποιος δεν μπορεί να το δει δεν θα μπορούσε ποτέ να το ανοίξει. Ένα μέλος που προστέθηκε πριν από αυτόν τον κανόνα παραμένει στη λίστα, με μια σημείωση στην κάρτα του. Κανείς δεν μπορεί να προστεθεί δύο φορές.',
            'p2' => 'Οι ρόλοι προέρχονται από το **Έργα - Ρυθμίσεις - Ρόλοι**, που ξεκινά με τους ρόλους τύπου PRINCE2 (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance και Project Support) συν Μέλος ομάδας και Ενδιαφερόμενος.',
            'p3' => 'Τα άτομα ενός έργου είναι οι στήλες του πίνακα RACI του, οπότε η αφαίρεση κάποιου αφαιρεί και τα γράμματα RACI του· οι εργασίες που του έχουν ανατεθεί δεν αλλάζουν. Η συμμετοχή σε ένα έργο μετράει και για τα δικαιώματα: ένας τεχνικός που είναι μέλος, ή που ανήκει σε ομάδα που είναι μέλος, αποτελεί μέρος της ομάδας του έργου (δείτε Ρυθμίσεις και δικαιώματα). **Ένα άτομο από τα Άτομα δεν έχει λογαριασμό FreeITSM και δεν μπορεί να ανοίξει το έργο** - βρίσκεται σε αυτό ώστε το έργο να καταγράφει τον ρόλο του: έναν ρόλο, μια στήλη στον πίνακα RACI, μια θέση στον χάρτη ενδιαφερομένων και στο πλάνο επικοινωνίας. Οι τεχνικοί βλέπουν το έργο στη σελίδα του ατόμου στα Άτομα και μια εγκεκριμένη αναφορά μπορεί να σταλεί σε αυτό με email.',
            'p4' => '**Ποιος μπορεί να το δει** (στη φόρμα του έργου): **Όλοι με πρόσβαση στα Έργα**, ή **Μόνο τα μέλη** - μόνο ο υπεύθυνος έργου, όποιος το δημιούργησε, τα μέλη του (άμεσα ή μέσω ομάδας) και όσοι διαχειρίζονται τα Έργα. Για εργασίες ανθρώπινου δυναμικού, ασφάλειας ή εμπιστευτικές. Για όλους τους άλλους ένα έργο μόνο για μέλη δεν υπάρχει: ούτε στο χαρτοφυλάκιο, την αναζήτηση, τα Άτομα, το Watchtower, το Warbot ή το API, και οι ημερομηνίες του μένουν εκτός του κοινού Ημερολογίου. Η Δυναμικότητα εξακολουθεί να μετράει τις εργασίες του, ως «Ένα έργο μόνο για μέλη». Όποιον ζητήσετε να εγκρίνει ή να υπογράψει πρέπει να είναι μέλος για να το ανοίξει. Τα νέα έργα ξεκινούν όπως ορίζει το Έργα -> Ρυθμίσεις -> Γενικά.',
            'p5' => '**Ποιος πρέπει να ξέρει;** - ο χάρτης ενδιαφερομένων. Το **Τοποθέτηση** σε ένα μέλος ορίζει την **ισχύ** του (πόσο μπορεί να επηρεάσει το έργο) και το **ενδιαφέρον** του (πόσο το επηρεάζει το έργο), από 1 έως 5, πού βρίσκεται (υποστηρικτής-πρωταθλητής, υποστηρικτής, ουδέτερος, σκεπτικιστής ή εμπόδιο) και πώς ενημερώνεται. Ο χάρτης βάζει τον καθένα σε ένα τεταρτημόριο - στενή διαχείριση, ικανοποίηση, ενημέρωση, παρακολούθηση (το 3 και πάνω θεωρείται υψηλό) - και το **πλάνο επικοινωνίας** από κάτω παραθέτει όλους όσους έχουν τοποθετηθεί, με πρώτους τους σημαντικότερους. Προσθέστε το διοικητικό συμβούλιο, τους χορηγούς και τα επηρεαζόμενα άτομα ως μέλη (μαζί και Άτομα από την ενότητα Άτομα) για να τα τοποθετήσετε.',
        ],
        'scope' => [
            'nav' => 'Πεδίο',
            'title' => 'Πεδίο και MoSCoW',
            'intro' => 'Τι παραδίδει το έργο, ταξινομημένο κατά προτεραιότητα.',
            'p1' => 'Η καρτέλα Πεδίο είναι ένας πίνακας με τα παραδοτέα και τις απαιτήσεις του έργου σε πέντε στήλες: Must, Should, Could, Won\'t (αυτή τη φορά) και Χωρίς προτεραιότητα. Πληκτρολογήστε στο πλαίσιο στο κάτω μέρος μιας στήλης για να προσθέσετε εκεί ένα στοιχείο και σύρετε μια κάρτα σε άλλη στήλη για να αλλάξετε την προτεραιότητά της - η μετακίνηση καταγράφεται στο ιστορικό.',
            'p2' => 'Πατήστε μια κάρτα για να την ανοίξετε. Εκτός από τον τίτλο και την προτεραιότητά της έχει κατάσταση (Προτεινόμενο, Συμφωνημένο, Σε εξέλιξη, Αποδεκτό ή Εγκαταλείφθηκε), τη φάση στην οποία ανήκει, μια περιγραφή και το **Ολοκληρώνεται όταν...** - πώς θα ξέρετε ότι έχει παραδοθεί. Η διαγραφή ενός παραδοτέου διαγράφει τη γραμμή του στον πίνακα RACI.',
        ],
        'raci' => [
            'nav' => 'RACI',
            'title' => 'Ποιος κάνει τι: RACI',
            'intro' => 'Τα άτομα στην κορυφή, τα παραδοτέα στο πλάι.',
            'p1' => 'Η καρτέλα RACI είναι ένα πλέγμα με τα άτομα του έργου (στήλες) έναντι των παραδοτέων του (γραμμές), οπότε χρειάζεται και τα δύο: προσθέστε πρώτα άτομα στην καρτέλα Άτομα και παραδοτέα στην καρτέλα Πεδίο. Τα παραδοτέα που έχουν εγκαταλειφθεί παραλείπονται.',
            'p2' => 'Πατήστε ένα κελί για να το περάσετε από τα R, A, C, I και πάλι σε κενό. Κάθε παραδοτέο έχει ένα άτομο υπόλογο: αν ορίσετε A σε δεύτερο άτομο, το προηγούμενο γίνεται Υπεύθυνο εκτέλεσης (Responsible), επειδή εξακολουθεί να κάνει τη δουλειά. Μια γραμμή χωρίς υπόλογο ή χωρίς υπεύθυνο εκτέλεσης επιτρέπεται όσο συντάσσετε και επισημαίνεται κάτω από το όνομα του παραδοτέου.',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'Το αρχείο RAID και ο θερμικός χάρτης',
            'intro' => 'Τι μπορεί να πάει στραβά, τι υποθέτετε, τι έχει πάει στραβά, τι περιμένετε και τι αποφασίσατε.',
            'p1' => 'Η καρτέλα RAID καταγράφει έξι είδη εγγραφών: κινδύνους, παραδοχές, ζητήματα, εξαρτήσεις, αποφάσεις και διδάγματα. Κάθε μία έχει τίτλο, λεπτομέρειες, υπεύθυνο, ημερομηνία ανασκόπησης και κατάσταση, Ανοιχτή ή Κλειστή. Τα κουμπιά στην κορυφή φιλτράρουν ανά είδος και δείχνουν πόσες από κάθε είδος είναι ανοιχτές· το **Εμφάνιση κλειστών** φέρνει πίσω τις κλειστές εγγραφές στη λίστα. Η καταγραφή, το κλείσιμο, το ξανάνοιγμα και η διαγραφή μιας εγγραφής καταγράφονται όλα στο ιστορικό.',
            'p2' => 'Ένας κίνδυνος έχει πιθανότητα και επίπτωση, η καθεμία σε κλίμακα πέντε βαθμίδων, και μια **βαθμολογία** ίση με την πιθανότητα επί την επίπτωση, από 1 έως 25. Μπορεί επίσης να έχει απόκριση (Αποφυγή, Μείωση, Μεταφορά, Αποδοχή ή Επιμερισμός) και ένα πλάνο για το πώς θα αντιμετωπιστεί. Ένα ζήτημα έχει επίπτωση και μπορεί να συσχετιστεί με ένα αίτημα, εφόσον μπορείτε να ανοίξετε το αίτημα και ανήκει στην εταιρεία του έργου.',
            'p3' => 'Ο θερμικός χάρτης, **Τι μπορεί να πάει στραβά;**, τοποθετεί κάθε ανοιχτό κίνδυνο που έχει και πιθανότητα και επίπτωση σε ένα πλέγμα πέντε επί πέντε, με απόχρωση από πράσινο έως κόκκινο ανάλογα με τη βαθμολογία. Πατήστε ένα τετράγωνο για να δείτε μόνο αυτούς τους κινδύνους· πατήστε το ξανά, ή το **Εμφάνιση όλων**, για να καθαρίσει. Οι λέξεις στις δύο κλίμακες προέρχονται από το **Έργα - Ρυθμίσεις - RAID**.',
            'p5' => 'Μια **εξάρτηση** είναι κάτι που το έργο χρειάζεται από έξω - ο ιδιοκτήτης που ολοκληρώνει τις εργασίες διαμόρφωσης, ένας προμηθευτής που παραδίδει, μια άλλη ομάδα. Η ημερομηνία της είναι το πότε χρειάζεται· κλείστε την όταν φτάσει. Μια **απόφαση** καταγράφεται πριν ληφθεί, με την ημερομηνία έως την οποία πρέπει να ληφθεί, και κλείνει όταν ληφθεί, με **Αποφασίστηκε από** (οποιοδήποτε όνομα - ο χορηγός, το συμβούλιο), **Αποφασίστηκε στις** και **Γιατί**. Επιλέξτε **Αποφάσεις** για να τις δείτε ως αρχείο αποφάσεων. Μια εξάρτηση ή απόφαση που παραμένει ανοιχτή μετά την ημερομηνία της κάνει το έργο πορτοκαλί.',
            'p6' => 'Ανοίξτε μια αποθηκευμένη εγγραφή για να την **Κλιμακώσετε** - όταν χρειάζεται κάποιον πάνω από τον υπεύθυνο έργου - με μια γραμμή που λέει τι χρειάζεται. Εμφανίζεται στην Επισκόπηση, σημειωμένη στην καρτέλα RAID και στην κάρτα του χαρτοφυλακίου, μέχρι να **Αποκλιμακωθεί** ή να κλείσει· ο υπεύθυνος έργου ειδοποιείται και μια ροή εργασιών μπορεί να ειδοποιήσει τον χορηγό. Οι **Ενέργειες παρακολούθησης** είναι εργασίες του έργου, που δημιουργούνται από την εγγραφή - ό,τι συμφωνήθηκε μετά από μια απόφαση, η μετριαστική ενέργεια για έναν κίνδυνο - με το πλήθος των ολοκληρωμένων να φαίνεται στο αρχείο.',
            'p4' => 'Ανοίξτε ένα αποθηκευμένο **δίδαγμα** και πατήστε **Γνωσιακή βάση** για να το μετατρέψετε σε πρόχειρο άρθρο της Γνωσιακής βάσης: οι λεπτομέρειές του γίνονται το άρθρο, με σύνδεσμο πίσω στο έργο, και συσχετίζεται στην καρτέλα Συνδέσεις. Διαβάστε το στη Γνωσιακή βάση και μετά δημοσιεύστε το. Ανοίξτε ένα αποθηκευμένο **ζήτημα** και πατήστε **Δημιουργία** για να δημιουργήσετε από αυτό ένα νέο αίτημα αντί να συσχετίσετε ένα που υπάρχει ήδη: εσείς είστε ο αιτών, πηγαίνει στον υπεύθυνο του ζητήματος (ή σε εσάς), ανήκει στην εταιρεία του έργου και το ζήτημα και το έργο συσχετίζονται με αυτό. Το καθένα γίνεται μία φορά ανά εγγραφή και απαιτεί πρόσβαση στη Γνωσιακή βάση ή στα Αιτήματα, εκτός από το δικαίωμα αλλαγής του έργου.',
            'p7' => 'Η **Εξαγωγή** (δίπλα στο Εμφάνιση κλειστών) κατεβάζει ολόκληρο το αρχείο - κάθε τύπο, ανοιχτό και κλειστό - ως βιβλίο Excel ή αρχείο CSV, με υπευθύνους, βαθμολογίες, αποκρίσεις, αποφάσεις και ενέργειες παρακολούθησης.',
        ],
        'gates' => [
            'nav' => 'Πύλες',
            'title' => 'Πύλες, ανοχές και εξαιρέσεις',
            'intro' => 'Οι έλεγχοι στους οποίους λογοδοτεί ένα σταδιακό έργο, με το στυλ του PRINCE2.',
            'p1' => 'Η καρτέλα Πύλες περιέχει τρία πράγματα. Η **επιχειρηματική περίπτωση** λέει γιατί αξίζει να γίνει το έργο - τα οφέλη, το κόστος και οι κίνδυνοι - και υπάρχει για να ανασκοπείται σε κάθε πύλη. Οι **ανοχές** λένε πόσο μπορεί να παρεκκλίνει το έργο πριν χρειαστεί απόφαση. Οι **πύλες σταδίων** καταγράφουν μια απόφαση στο τέλος κάθε σταδίου.',
            'p2' => 'Υπάρχουν δύο ανοχές και αν αφήσετε μία κενή, απενεργοποιείται. Οι **Επιτρεπόμενες ημέρες καθυστέρησης** ξεπερνιούνται όταν η ημερομηνία-στόχος λήξης, ή η ημερομηνία λήξης του σταδίου σε εξέλιξη, είναι περισσότερες από τόσες ημέρες στο παρελθόν ενώ υπάρχει ακόμη ανοιχτή δουλειά. Η **Ανώτατη επιτρεπόμενη βαθμολογία κινδύνου** ξεπερνιέται όταν ένας ανοιχτός κίνδυνος στο αρχείο RAID βαθμολογείται υψηλότερα από αυτήν.',
            'p3' => 'Η υπέρβαση μιας ανοχής κάνει το έργο **εξαίρεση**. Όσο διαρκεί, η υπολογισμένη πορεία είναι Εκτός πλάνου, ένα banner **Η ανοχή ξεπεράστηκε** ονομάζει κάθε μία στις καρτέλες Επισκόπηση και Πύλες και η κάρτα του έργου στο χαρτοφυλάκιο φέρει ένα σήμα **Εξαίρεση**. Οι εξαιρέσεις υπολογίζονται κάθε φορά που εμφανίζεται το έργο, δεν αποθηκεύονται ποτέ, οπότε καθαρίζουν μόνες τους μόλις το έργο επανέλθει εντός των ανοχών του. Ισχύουν μόνο για ένα ενεργό έργο με ενεργοποιημένο το εργαλείο Πύλες, και μια πορεία που ορίστηκε με το χέρι μένει όπως ορίστηκε.',
            'p4' => 'Πατήστε **Απόφαση** σε ένα στάδιο που είναι σε εξέλιξη ή ολοκληρωμένο (ένα προγραμματισμένο στάδιο δεν έχει κουμπί), επιλέξτε μια απόφαση και προσθέστε σημειώσεις. Η απόφαση, ποιος την πήρε και πότε μένουν στο στάδιο και καταγράφονται στο ιστορικό. Ένα «προχωράμε» που καταγράφεται σε ένα στάδιο που έχει ήδη ολοκληρωθεί καταγράφει μόνο την απόφαση: δεν ξεκινά άλλο στάδιο.',
            'p5' => 'Πριν από μια απόφαση, η πύλη ελέγχει τις **αλλαγές** που συσχετίζονται στην καρτέλα Συνδέσεις. Όσες είναι ακόμη ανοιχτές και μη εγκεκριμένες - σε αναμονή έγκρισης, ή πρόχειρες που κανείς δεν έχει υποβάλει - παρατίθενται στο παράθυρο της πύλης με την κατάστασή τους και την προγραμματισμένη έναρξη, και το στάδιο σε εξέλιξη φέρει ένα σήμα που λέει πόσες είναι. Είναι προειδοποίηση, όχι φραγή: η απόφαση παραμένει δική σας. Το βλέπετε μόνο αν μπορείτε να ανοίξετε τις Αλλαγές.',
            'p6' => 'Κάθε πύλη μπορεί να έχει μια **λίστα ελέγχου** με ό,τι πρέπει να ισχύει πριν από ένα «προχωράμε»: έναν **έλεγχο** για τσεκάρισμα· ένα **έγγραφο** - που ολοκληρώνεται επιλέγοντας ένα από τα αρχεία του έργου στην καρτέλα **Έγγραφα** (το πλάνο αναίρεσης, η αναφορά δοκιμών)· μια **έγκριση** από ένα συγκεκριμένο άτομο, που ειδοποιείται στο καμπανάκι και είναι ο μόνος που μπορεί να την υπογράψει· ή μια συσχετισμένη **αλλαγή** που πρέπει να εγκριθεί στις Αλλαγές. Μετατρέψτε μια πύλη σε **Πύλη έναρξης λειτουργίας** και αποκτά μια αρχική λίστα ελέγχου - υπογεγραμμένες δοκιμές αποδοχής χρηστών, ένα πλάνο αναίρεσης, εγκεκριμένη αλλαγή, συμφωνημένη παράδοση στην υποστήριξη - για να την κρατήσετε, να την αλλάξετε ή να της προσθέσετε. Μέχρι να ολοκληρωθεί κάθε στοιχείο, ένα «προχωράμε» απορρίπτεται (ένα «σταματάμε» ποτέ)· το Έργα - Ρυθμίσεις - Γενικά μπορεί να το κάνει προειδοποίηση, και τότε ό,τι έμενε ανοιχτό γράφεται στις σημειώσεις της πύλης.',
            'go_d' => 'Κλείνει το στάδιο και ξεκινά το επόμενο προγραμματισμένο.',
            'go_with_conditions_d' => 'Το ίδιο με το Προχωράμε, με τους όρους γραμμένους στις σημειώσεις - είναι υποχρεωτικοί.',
            'stop_d' => 'Καταγράφει ότι το έργο δεν πρέπει να συνεχίσει όπως είχε σχεδιαστεί. Δεν αλλάζει κανένα στάδιο: το τι θα γίνει στη συνέχεια το αποφασίζουν όσοι τρέχουν το έργο.',
        ],
        'templates' => [
            'nav' => 'Πρότυπα',
            'title' => 'Ξεκινήστε από ένα πρότυπο',
            'intro' => 'Ένα έργο που φτάνει ήδη σχεδιασμένο.',
            'p1' => 'Όταν δημιουργείτε ένα έργο, το **Έναρξη από** προσφέρει πρότυπα: μια μετακόμιση γραφείου, μια ανανέωση φορητών, μια μετεγκατάσταση αλληλογραφίας, μια υλοποίηση των Windows 11 και μια βελτίωση του service desk περιλαμβάνονται έτοιμα. Επιλέξτε ένα και το έργο δημιουργείται με τα στάδια, τις εργασίες, το πεδίο εφαρμογής, τους κινδύνους και τα όριά του ήδη στη θέση τους, ενώ ο τρόπος λειτουργίας, το χρώμα, το εικονίδιο και ο στόχος συμπληρώνονται για εσάς. Ό,τι πληκτρολογήσετε στη φόρμα υπερισχύει του προτύπου.',
            'p2' => 'Ένα πρότυπο κρατά τις ημερομηνίες του ως ημέρες από την έναρξη, επομένως κάθε ημερομηνία προγραμματίζεται από την **ημερομηνία έναρξης** που δίνετε - σήμερα, αν την αφήσετε κενή - και η ημερομηνία-στόχος λήξης ακολουθεί, εκτός αν ορίσετε δική σας. Οι εργασίες είναι συνηθισμένες εργασίες, δεν έχουν ανατεθεί σε κανέναν και τίποτα δεν έχει σημειωθεί ως ολοκληρωμένο. Ένας στόχος πάγιων που απαιτεί κατάσταση ή τοποθεσία με όνομα (για παράδειγμα «Αποσυρμένο») προστίθεται μόνο όταν το όνομα αυτό υπάρχει στην εγκατάστασή σας.',
            'p3' => 'Για να φτιάξετε δικό σας, ανοίξτε ένα έργο που πήγε καλά και πατήστε **Πρότυπο**. Επιλέξτε τι θα κρατήσετε: τα στάδια και τις εργασίες, το πεδίο εφαρμογής, τους κινδύνους και τις παραδοχές, τα όρια (συμπεριλαμβανομένης της επιτρεπόμενης υπέρβασης) και τους στόχους πάγιων. Για να αλλάξετε ένα πρότυπο, ξεκινήστε ένα έργο από αυτό, αλλάξτε το έργο, πατήστε **Πρότυπο** και επιλέξτε **Αντικατάσταση ενός από τα πρότυπά σας** - τα ενσωματωμένα μπορούν να αντιγραφούν με αυτόν τον τρόπο, ποτέ να αντικατασταθούν. Τα άτομα, η εταιρεία, οι συσχετίσεις και η πρόοδος δεν διατηρούνται ποτέ, ώστε ένα πρότυπο να λειτουργεί για οποιαδήποτε εταιρεία. Το **Έργα - Ρυθμίσεις - Πρότυπα** τα εμφανίζει όλα: αποκρύψτε ένα ενσωματωμένο που δεν χρησιμοποιείτε ποτέ, και μετονομάστε, απενεργοποιήστε ή διαγράψτε τα δικά σας. Η αποθήκευση και η διαχείριση προτύπων απαιτεί το δικαίωμα Πρότυπα· όποιος μπορεί να δημιουργεί έργα μπορεί να ξεκινήσει από ένα πρότυπο.',
            'p4' => 'Από την έκδοση 3.3.0 ένα πρότυπο μεταφέρει επίσης τις **εξαρτήσεις** του σχεδίου, τη **λίστα ελέγχου πύλης** κάθε σταδίου (και αν πρόκειται για πύλη go-live - χωρίς να έχει οριστεί ακόμη κάποιος για την έγκριση) και, αν τα κρατήσετε, τα **οφέλη** με τους στόχους τους (ποτέ τις βασικές τιμές - αυτές μετριούνται στο νέο έργο). Τα πέντε ενσωματωμένα πρότυπα συνοδεύονται και από τα τρία.',
        ],
        'targets' => [
            'nav' => 'Στόχοι πάγιων',
            'title' => 'Στόχοι πάγιων: πρόοδος κατευθείαν από τα Πάγια',
            'intro' => '«312 από 480 φορητά αντικαταστάθηκαν», μετρημένα από τα ίδια τα πάγια.',
            'p1' => 'Ένας στόχος πάγιων βρίσκεται στην Επισκόπηση ενός έργου και μετρά κάτι στα Πάγια: τα Latitude 5430 που έχουν αποσυρθεί, τα μηχανήματα Windows που έχουν πλέον Windows 11, τα φορητά με ενεργό BitLocker. Η μέτρηση υπολογίζεται κάθε φορά που ανοίγει η σελίδα, οπότε μόλις κάποιος αλλάξει ένα πάγιο το έργο προχωρά - κανείς δεν χρειάζεται να θυμάται να σημειώσει κάτι. Κάθε στόχος σχεδιάζει μια γραμμή προόδου, με ένα σημείο την ημέρα από την ημέρα που ρυθμίστηκε.',
            'p2' => 'Επιλέξτε **ποια πάγια**: είτε εκείνα που **ταιριάζουν** με έναν τύπο ή/και ένα πεδίο που περιέχει κάποιο κείμενο (το μοντέλο περιέχει 5430), είτε εκείνα που είναι **συσχετισμένα με αυτό το έργο** στην καρτέλα Συνδέσεις. Έπειτα επιλέξτε **πότε θεωρείται ότι ένα είναι ολοκληρωμένο**: μια κατάσταση, μια τοποθεσία, το λειτουργικό σύστημα, η έκδοση χαρακτηριστικών, το μοντέλο, ο κατασκευαστής, το BitLocker ή η έκδοση TPM. Το παράθυρο δείχνει πόσα πάγια ταιριάζουν και πόσα έχουν ολοκληρωθεί, καθώς πληκτρολογείτε. Ένας στόχος μετρά πάντα μόνο πάγια της δικής του εταιρείας του έργου.',
            'p3' => 'Κάθε στόχος έχει μια ημερομηνία - τη δική του ή την ημερομηνία-στόχο λήξης του έργου. Ένας στόχος που έχει περάσει την ημερομηνία του και δεν έχει ολοκληρωθεί κάνει το έργο κόκκινο· ένας που υστερεί περισσότερο από 25 μονάδες σε σχέση με μια ευθεία γραμμή από την ημέρα που ορίστηκε έως την ημερομηνία του το κάνει πορτοκαλί. Το **Απομένουν** εμφανίζει τα πάγια που απομένουν, το καθένα ως σύνδεσμο προς το πάγιο. Η ρύθμιση ενός στόχου και η προβολή των πάγιων που υστερούν απαιτούν πρόσβαση στα Πάγια καθώς και δικαίωμα αλλαγής του έργου· η αλλαγή του κανόνα ξεκινά ξανά τη γραμμή του.',
        ],
        'health' => [
            'nav' => 'Πορεία',
            'title' => 'Πώς υπολογίζεται η πορεία',
            'intro' => 'Από το σχέδιο, όχι από τη διάθεση κάποιου.',
            'p1' => 'Εκτός αν κάποιος την ορίσει με το χέρι, η πορεία ενός ενεργού έργου υπολογίζεται από τις εργασίες και την ημερομηνία-στόχο του κάθε φορά που εμφανίζεται. Τα παρακάτω μεγέθη είναι οι προεπιλογές· μπορούν να αλλάξουν στο **Έργα - Ρυθμίσεις - Πορεία**.',
            'green_d' => 'Δεν ισχύει τίποτα από τα παρακάτω.',
            'amber_d' => 'Τουλάχιστον μία ανοιχτή εργασία έχει καθυστερήσει, χάθηκε ένα ορόσημο ή μια εξάρτηση ή απόφαση έχει περάσει την ημερομηνία της (καθεμία από τις δύο μπορεί να οριστεί σε κόκκινο ή σε τίποτα, στο Έργα - Ρυθμίσεις - Πορεία), η ημερομηνία-στόχος πλησιάζει και έχει γίνει πολύ λίγη δουλειά - από προεπιλογή μέσα σε 14 ημέρες με λιγότερο από τα τρία τέταρτα ολοκληρωμένα - ή υπάρχει άνοδος στα συσχετισμένα αιτήματα: από προεπιλογή 5 ή περισσότερα τις τελευταίες 7 ημέρες, που μετά από ένα go-live συνήθως σημαίνει ότι κάτι χρειάζεται διόρθωση.',
            'red_d' => 'Η ημερομηνία-στόχος έχει περάσει με δουλειά ακόμη ανοιχτή, πολύ μεγάλο μέρος της ανοιχτής δουλειάς έχει καθυστερήσει - από προεπιλογή το ένα τέταρτο ή περισσότερο - ή το έργο έχει ξεπεράσει ένα από τα όριά του (βλ. Πύλες). Μετρούν και οι στόχοι πάγιων: ένας που έχει περάσει την ημερομηνία του κάνει το έργο κόκκινο, ένας που υστερεί αρκετά κάνει ένα πράσινο έργο πορτοκαλί (βλ. Στόχοι πάγιων).',
            'p2' => 'Για να την ορίσετε μόνοι σας, επεξεργαστείτε το έργο και επιλέξτε μια πορεία· προσθέστε μια γραμμή που εξηγεί γιατί. Επιλέξτε **Υπολογισμός από το σύστημα** για να την επιστρέψετε. Τα κλειστά και τα ακυρωμένα έργα δεν έχουν πορεία.',
        ],
        'tasks' => [
            'nav' => 'Εργασίες',
            'title' => 'Οι εργασίες του έργου είναι συνηθισμένες εργασίες',
            'intro' => 'Μία λίστα εργασιών ανά άτομο, όχι δύο.',
            'p1' => 'Μια εργασία που προστίθεται σε ένα έργο είναι μια κανονική εργασία: εμφανίζεται στον πίνακα Εργασιών, μπορεί να ανατεθεί, να προγραμματιστεί, να χρονομετρηθεί, να σχολιαστεί και να αποκτήσει υποεργασίες και λίστες ελέγχου, και στέλνει τα συνηθισμένα email και τις ειδοποιήσεις. Η πρόοδος μετρά τις εργασίες ανώτατου επιπέδου· οι υποεργασίες ανήκουν στην εργασία τους.',
            'p2' => 'Η διαγραφή ενός έργου δεν διαγράφει ποτέ τις εργασίες του. Παραμένουν στον πίνακα Εργασιών και απλώς παύουν να ανήκουν σε έργο. Η αφαίρεση μιας φάσης λειτουργεί με τον ίδιο τρόπο: οι εργασίες της παραμένουν στο έργο, απλώς όχι σε φάση.',
        ],
        'contractors' => [
            'nav' => 'Εξωτερικοί συνεργάτες',
            'title' => 'Εργασία που γίνεται από εξωτερικούς συνεργάτες',
            'intro' => 'Όταν μια εξωτερική εταιρεία αναλαμβάνει μέρος του έργου - την καλωδίωση, τη μετακόμιση, την εγκατάσταση.',
            'p1' => 'Μια εργασία μπορεί να δοθεί σε έναν **εξωτερικό συνεργάτη**: έναν προμηθευτή από τις Συμβάσεις και, αν θέλετε, ένα άτομο εκεί. Στο παράθυρο της εργασίας στον πίνακα Εργασιών, επιλέξτε τους στα **Εξωτερικός συνεργάτης** και **Επαφή εκεί**. Ο **Ανατεθειμένος σε** παραμένει το άτομο από εσάς που είναι υπεύθυνο για την εργασία και παρακολουθεί την εταιρεία - άρα μια εργασία εξωτερικού συνεργάτη έχει και τα δύο. Για να επιλέξετε προμηθευτή χρειάζεστε πρόσβαση στις Συμβάσεις· όποιος μπορεί να δει την εργασία βλέπει με ποιον είναι.',
            'p2' => 'Οι εργασίες εξωτερικών συνεργατών φέρουν το όνομα της εταιρείας στο Σχέδιο, στο Χρονοδιάγραμμα και στον πίνακα Εργασιών, όπου ένα φίλτρο **Εξωτερικός συνεργάτης** δείχνει τη δουλειά μιας εταιρείας, όλη τη δουλειά εξωτερικών συνεργατών ή καμία. Στην καρτέλα **Άτομα**, το **Προσθήκη ατόμου - Εξωτερικός συνεργάτης** βάζει μια εταιρεία, ή ένα άτομο εκεί, στο έργο με έναν ρόλο, ώστε να μπορεί να βρίσκεται στον πίνακα RACI και στον χάρτη ενδιαφερομένων. Η σελίδα του προμηθευτή στα Άτομα εμφανίζει κάθε εργασία που έχει μαζί τους.',
            'p3' => 'Η δουλειά των εξωτερικών συνεργατών δεν υπολογίζεται στο φορτίο κανενός στη **Χωρητικότητα** - εμφανίζεται από κάτω, μία γραμμή ανά εταιρεία με τις ανοιχτές εργασίες της, τις ώρες που απομένουν και πόσες έχουν καθυστερήσει. Η σύνοψη των εργασιών που καθυστερούν, οι ενημερώσεις του AI και το **Ρωτήστε το AI** αναφέρουν ποια καθυστερημένη δουλειά είναι σε εξωτερικό συνεργάτη, και το Ρωτήστε το AI μπορεί να προτείνει να δοθεί μια εργασία σε έναν από αυτούς.',
            'p4' => 'Το **Email στους εξωτερικούς συνεργάτες** (Έργα - Ρυθμίσεις - Γενικά) είναι αρχικά απενεργοποιημένο: η δουλειά των εξωτερικών συνεργατών παρακολουθείται εδώ και την ακολουθείτε εσείς. Ενεργοποιήστε το και το άτομο στην εταιρεία λαμβάνει email όταν του ανατίθεται μια εργασία, δύο ημέρες πριν από την προθεσμία και μία φορά αν χαθεί - από το γραμματοκιβώτιο εξερχομένων σας, με την εργασία, τις ημερομηνίες και σε ποιον να απαντήσει εδώ. Στέλνονται μόνο οι εργασίες με άτομο που έχει διεύθυνση email· κάθε email εμφανίζεται στο αρχείο αποστολών ως **Εργασία για εξωτερικό συνεργάτη**.',
        ],
        'connections' => [
            'nav' => 'Συνδέσεις',
            'title' => 'Σύνδεση ενός έργου με όλα τα υπόλοιπα',
            'intro' => 'Εξοπλισμός, αλλαγές, αιτήματα, συμβάσεις, στοιχεία διαμόρφωσης, γνώση και προβλήματα.',
            'p1' => 'Η καρτέλα Συνδέσεις συσχετίζει ένα έργο με τις εγγραφές που αγγίζει: τα φορητά που αντικαθίστανται, τις αλλαγές που δημιουργεί (και αν έχουν εγκριθεί), τα αιτήματα που προκάλεσε, τις συμβάσεις προμηθευτών στις οποίες στηρίζεται, τα συστήματα στο CMDB, τα εγχειρίδια διαδικασιών στη Γνωσιακή βάση και τα προβλήματα που υπάρχει για να διορθώσει. Πληκτρολογήστε στο πλαίσιο κάτω από ένα είδος για αναζήτηση και επιλέξτε ένα αποτέλεσμα για να το συσχετίσετε. Η Επισκόπηση δείχνει πόσα από το καθένα είναι συνδεδεμένα.',
            'p2' => 'Βλέπετε ένα είδος μόνο αν μπορείτε να ανοίξετε την ενότητά του, και μια σύνδεση μόνο αν μπορείτε να ανοίξετε την εγγραφή στο άλλο άκρο. Σε μια εγκατάσταση με περισσότερες από μία εταιρείες, ο εξοπλισμός, οι αλλαγές, τα αιτήματα, τα προβλήματα και τα στοιχεία διαμόρφωσης πρέπει να ανήκουν στην εταιρεία του ίδιου του έργου. Η αποσύνδεση δεν αλλάζει ποτέ την ίδια την εγγραφή, και και οι δύο ενέργειες καταγράφονται στο ιστορικό του έργου.',
            'p3' => 'Κάθε εγγραφή δείχνει τα έργα της και από τη δική της πλευρά. Ένα **πρόβλημα** έχει ένα πλαίσιο **Έργα** που εμφανίζει τα έργα στα οποία συμμετέχει, με την πορεία και την πρόοδό τους, και **Προσθήκη σε έργο** για να το συσχετίσετε με ένα ενεργό έργο από εκεί - η ίδια σύνδεση όπως στην καρτέλα Συνδέσεις του έργου.',
        ],
        'calendar' => [
            'nav' => 'Στο Ημερολόγιο',
            'title' => 'Οι ημερομηνίες του έργου στο Ημερολόγιο',
            'intro' => 'Ημερομηνίες-στόχοι λήξης, λήξεις σταδίων και ορόσημα, εκεί που ήδη κοιτάζει η υπόλοιπη ομάδα.',
            'p1' => 'Κάθε προτεινόμενο ή ενεργό έργο βάζει την ημερομηνία-στόχο λήξης του στο κοινό Ημερολόγιο ως «Προθεσμία έργου», και κάθε στάδιο, φάση ή sprint που δεν έχει κλείσει βάζει εκεί την ημερομηνία λήξης του, όπως και κάθε ορόσημο μέχρι να επιτευχθεί. Είναι εγγραφές ολοήμερες σε μια κατηγορία με όνομα Έργα, την οποία μπορείτε να μετονομάσετε ή να χρωματίσετε ξανά στο Ημερολόγιο. Αλλάξτε μια ημερομηνία στο έργο και το Ημερολόγιο ακολουθεί· κλείστε ένα στάδιο, ή θέστε το έργο σε αναμονή, κλείστε το ή ακυρώστε το, και οι εγγραφές του φεύγουν. Το **Έργα - Ρυθμίσεις - Γενικά** ορίζει αν το Ημερολόγιο δείχνει όλες, μόνο τις ημερομηνίες-στόχους λήξης ή τίποτα.',
            'p2' => 'Οι εγγραφές γράφονται από τα Έργα, επομένως μια αλλαγή που γίνεται σε μία στο Ημερολόγιο αντικαθίσταται την επόμενη φορά που θα αλλάξει οποιοδήποτε έργο. Η διατύπωσή τους είναι στα αγγλικά, όπως και οι άλλες αυτόματες εγγραφές. Οι εγγραφές του Ημερολογίου δεν έχουν εταιρεία, επομένως σε μια εγκατάσταση με περισσότερες από μία εταιρείες όλοι όσοι μπορούν να ανοίξουν το Ημερολόγιο βλέπουν τις ημερομηνίες κάθε έργου.',
        ],
        'alerts' => [
            'nav' => 'Ειδοποιήσεις και ροές εργασιών',
            'title' => 'Ειδοποιήσεις, και έργα στις Ροές εργασιών',
            'intro' => 'Ο υπεύθυνος του έργου ενημερώνεται όταν κάτι τον χρειάζεται, και οι Ροές εργασιών μπορούν να ενεργήσουν.',
            'p1' => 'Το κουδούνι ειδοποιήσεων ενημερώνει τον υπεύθυνο ενός έργου όταν αλλάζει η πορεία του (πράσινο, πορτοκαλί ή κόκκινο, υπολογισμένη ή ορισμένη με το χέρι), όταν ξεπεράσει ένα όριο χρόνου ή κινδύνου, όταν ένα στάδιο, μια φάση ή ένα sprint λήγει σε 7 ημέρες και ξανά την προηγούμενη ημέρα, όταν ένα ορόσημο απέχει 7 ημέρες, την προηγούμενη ημέρα και αν χαθεί, και όταν κάποιος υποβάλλει, εγκρίνει ή απορρίπτει ένα αίτημα αλλαγής. Καθεμία λέγεται μία φορά, όταν συμβεί: ένα έργο που παραμένει κόκκινο δεν χτυπά κάθε ώρα, και μια υπέρβαση που εξαφανίζεται και ξαναγυρίζει είναι νέα είδηση. Κανείς δεν ενημερώνεται για μια αλλαγή που έκανε ο ίδιος. Κάθε άτομο μπορεί να τις απενεργοποιήσει, ή να ενεργοποιήσει ένα κουδούνι όταν κλείνει ένα στάδιο ή επιτυγχάνεται ένα ορόσημο, στο **Προτιμήσεις - Ειδοποιήσεις**.',
            'p2' => 'Οι ίδιες στιγμές είναι εναύσματα στις **Ροές εργασιών**: η πορεία ενός έργου αλλάζει, παραβιάζεται ένα όριο, κλείνει ένα στάδιο, ένα στάδιο λήγει σύντομα, ένα ορόσημο πλησιάζει, χάνεται ή επιτυγχάνεται, ένα αίτημα αλλαγής υποβάλλεται ή αποφασίζεται, και ένα έργο δημιουργείται, ενημερώνεται ή διαγράφεται. Μια ροή εργασιών μπορεί να δημοσιεύσει στο Teams ή στο Slack όταν ένα έργο γίνεται κόκκινο, να δημιουργήσει ένα αίτημα όταν παραβιάζεται ένα όριο, ή να στείλει email στο διοικητικό συμβούλιο όταν κλείνει ένα στάδιο, χρησιμοποιώντας το όνομα, τον κωδικό, την πορεία, τον υπεύθυνο και τις ημερομηνίες του έργου.',
            'p3' => 'Η πορεία και τα όρια υπολογίζονται από το σχέδιο, επομένως κάτι πρέπει να το ελέγχει. Η αποθήκευση οτιδήποτε σε ένα έργο ελέγχει αμέσως· διαφορετικά το προγραμματισμένο έργο ροών εργασιών το κάνει (cron/workflow_scheduled.php, μία φορά την ώρα αρκεί), και σε μια εγκατάσταση χωρίς προγραμματισμένα έργα, το άνοιγμα του χαρτοφυλακίου ελέγχει το πολύ κάθε 15 λεπτά. Μια εργασία που καθυστερεί κατά τη διάρκεια της νύχτας γίνεται αντιληπτή από όποιο προηγηθεί.',
            'p4' => '**Υπενθυμίσεις.** Κάθε υπεύθυνος έργου λαμβάνει ένα κουδούνι με τις **εργασίες που καθυστερούν** των ενεργών έργων του - εβδομαδιαία τη Δευτέρα, καθημερινά ή ποτέ (Έργα -> Ρυθμίσεις -> Γενικά, *Σύνοψη εργασιών που καθυστερούν*). Και όταν μια πρόταση, ένα αίτημα αλλαγής, μια έγκριση πύλης ή ένα προσχέδιο αναφοράς περιμένει **3 ημέρες** για απόφαση, όσοι την αποφασίζουν δέχονται υπενθύμιση - *περιμένει ακόμη την έγκρισή σας* - και ξανά κάθε 3 ημέρες (*Υπενθύμιση μετά από*· 0 = χωρίς υπενθυμίσεις). Τίποτα παλαιότερο από 45 ημέρες δεν υπενθυμίζεται.',
            'p5' => 'Το κουδούνι ειδοποιεί επίσης: τον υπεύθυνο του έργου όταν κάποιος κλιμακώνει μια εγγραφή RAID· τους εγκρίνοντες για μια νέα πρόταση, και όποιον την πρότεινε για την απόφαση· ένα συγκεκριμένο άτομο όταν χρειάζεται η έγκρισή του σε μια πύλη· τον υπεύθυνο ενός οφέλους και τον υπεύθυνο του έργου όταν είναι ώρα για επισκόπηση, ακόμη και μετά το κλείσιμο· και τον υπεύθυνο του έργου όταν έχει συνταχθεί μια προγραμματισμένη αναφορά. Καθένα από αυτά, η σύνοψη εργασιών που καθυστερούν και οι υπενθυμίσεις είναι επίσης εναύσματα στις **Ροές εργασιών**.',
        ],
        'budget' => [
            'nav' => 'Προϋπολογισμός',
            'title' => 'Ο προϋπολογισμός: προγραμματισμένος έναντι πραγματικού',
            'intro' => 'Πόσο υποτίθεται ότι θα κοστίσει το έργο, πόσο έχει κοστίσει και πόσο απέχουν.',
            'p1' => 'Η καρτέλα Προϋπολογισμός (ενεργή για τα έργα σε στάδια· ενεργοποιήστε την για άλλα από τα Εργαλεία) δείχνει τον προγραμματισμένο προϋπολογισμό, την πραγματική δαπάνη, το υπόλοιπο και πόσο έχει χρησιμοποιηθεί. Προσθέστε μια **γραμμή προϋπολογισμού** για καθετί στο οποίο περιμένετε να ξοδέψετε - υλικό, άδειες χρήσης, προμηθευτές - με το ποσό που προγραμματίστηκε και αυτό που έχει δαπανηθεί. Μια γραμμή μπορεί να αναφέρει μια σύμβαση που έχει συσχετιστεί στην καρτέλα Συνδέσεις: αν αφήσετε κενό το πραγματικό της ποσό, χρησιμοποιείται η αξία της σύμβασης. Μπορεί επίσης να φέρει ένα κέντρο κόστους της εταιρείας του έργου.',
            'p2' => 'Το **Εργατικό κόστος** είναι ο χρόνος που καταγράφεται στις εργασίες του έργου. Το Έργα - Ρυθμίσεις - Προϋπολογισμός αποφασίζει αν εμφανίζεται σε ώρες, αποτιμημένο με μία ωριαία τιμή (που ένα έργο μπορεί να παρακάμψει) ή αποτιμημένο με την τιμή κάθε τεχνικού. Κάθε τιμή ισχύει από μια ημερομηνία, ώστε μια νέα τιμή να μην αναπροσαρμόζει ποτέ χρόνο που έχει ήδη καταγραφεί, και η αλλαγή της ρύθμισης δεν ξαναγράφει τίποτα - ο χρόνος αποθηκεύεται ως χρόνος.',
            'p4' => 'Το **Πού πηγαίνουν τα χρήματα** απεικονίζει σε γράφημα τον προγραμματισμένο έναντι του πραγματικού ανά κατηγορία, με το εργατικό κόστος συμπεριλαμβανομένου μόλις αποτιμηθεί. Ο **Πίνακας** δείχνει τα ίδια μεγέθη ως πίνακα.',
            'p5' => 'Μια γραμμή μπορεί να πει **πότε**: την ημερομηνία που προγραμματίζεται να βγουν τα χρήματα και την ημερομηνία που βγήκαν. Η **Δαπάνη στον χρόνο** τα αθροίζει ανά ημέρα - προγραμματισμένα και δαπανημένα μέχρι τώρα - με μια διακεκομμένη **πρόβλεψη** από σήμερα έως την ημερομηνία-στόχο λήξης, και τον προϋπολογισμό, τον προϋπολογισμό της τελευταίας baseline και το όριο υπέρβασης ως γραμμές για σύγκριση. Η **Πρόβλεψη** είναι το πόσο αναμένεται τώρα να κοστίσει το έργο: η πρόβλεψη κάθε γραμμής (πληκτρολογήστε μία, αλλιώς είναι το μεγαλύτερο από το προγραμματισμένο και το δαπανημένο), συν το εργατικό κόστος - καταγεγραμμένο, και αυτό που απομένει στις εκτιμήσεις των ανοιχτών εργασιών, αποτιμημένο με τη σημερινή τιμή. Μια γραμμή εργατικού κόστους χωρίς πραγματικό ποσό είναι το σχέδιο για το εργατικό κόστος, ώστε αυτό να μην μετράται ποτέ δύο φορές. Το Έργα - Ρυθμίσεις - Προϋπολογισμός αποφασίζει αν μετρούν οι εκτιμήσεις, και αν η **Επιτρεπόμενη υπέρβαση** μετρά ό,τι έχει δαπανηθεί ή την πρόβλεψη - που προειδοποιεί νωρίτερα.',
            'p3' => 'Κάθε έργο κρατά το **νόμισμα** με το οποίο δημιουργήθηκε, και ποσά σε διαφορετικά νομίσματα δεν αθροίζονται ποτέ: μια σύμβαση σε άλλο νόμισμα εμφανίζεται στη γραμμή της αλλά δεν μετράται. Αν τα Έργα - Ρυθμίσεις επιτρέπουν στα έργα να επιλέγουν, το κουμπί Νόμισμα αλλάζει την ετικέτα του έργου - δεν μετατρέπει. Στην καρτέλα Πύλες, η **Επιτρεπόμενη υπέρβαση** ορίζει ένα όριο κόστους: αν ξεπεράσετε τον προϋπολογισμό περισσότερο από αυτό, το έργο γίνεται εξαίρεση και Εκτός πορείας.',
            'p6' => 'Η **Earned value** συγκρίνει τρεις γραμμές: την προγραμματισμένη αξία (ο προϋπολογισμός όπως προγραμματίστηκε να δαπανηθεί, από τις προγραμματισμένες ημερομηνίες των γραμμών), την αξία που κερδήθηκε (ο προϋπολογισμός επί το ποσοστό της δουλειάς που έγινε - με εκτιμώμενες ώρες, ή με εργασίες όταν δεν υπάρχουν εκτιμήσεις) και το πραγματικό κόστος. Ο **CPI** είναι η αξία που κερδήθηκε προς το πραγματικό κόστος - κάτω από 1, η δουλειά που έγινε κόστισε περισσότερο από ό,τι έπρεπε· ο **SPI** είναι η αξία που κερδήθηκε προς την προγραμματισμένη αξία - κάτω από 1, καθυστερεί σε σχέση με το σχέδιο· η **εκτίμηση στην ολοκλήρωση** είναι ο προϋπολογισμός διαιρεμένος με τον CPI.',
        ],
        'benefits' => [
            'nav' => 'Οφέλη',
            'title' => 'Οφέλη: απέδωσε το έργο;',
            'intro' => 'Τι υποτίθεται ότι βελτιώνει το έργο, μετρημένο από το σημείο εκκίνησης - και με επισκόπηση μετά το κλείσιμο, όταν φτάνουν τα περισσότερα οφέλη.',
            'p1' => 'Η καρτέλα **Οφέλη** (ενεργή για τα έργα σε στάδια· ενεργοποιήστε την για άλλα από τα Εργαλεία) εμφανίζει τι πρέπει να βελτιώσει το έργο. Κάντε **Προσθήκη** ενός: τι βελτιώνεται, πώς μετριέται και σε ποια μονάδα, ποια κατεύθυνση είναι καλύτερη (υψηλότερη ή χαμηλότερη), η **βασική τιμή** (πού βρίσκεται σήμερα), ο **στόχος** και η ημερομηνία έως την οποία πρέπει να επιτευχθεί, ένας υπεύθυνος και πότε γίνεται η επισκόπησή του. Κάθε όφελος δείχνει τη βασική τιμή, το τώρα και τον στόχο δίπλα-δίπλα με το πόσο έχει προχωρήσει, και ένα από τα εξής: δεν έχει μετρηθεί ακόμη, σε εξέλιξη, επιτεύχθηκε ή χάθηκε η ημερομηνία-στόχος.',
            'p2' => 'Το **Καταγραφή** προσθέτει μια μέτρηση - μια τιμή και την ημερομηνία που μετρήθηκε. Η πιο πρόσφατη είναι το «τώρα». Η καταγραφή της κοντά στην ημερομηνία επισκόπησης (έως 14 ημέρες νωρίτερα) μετρά ως επισκόπηση, και η επόμενη επισκόπηση μεταφέρεται κατά το διάστημα του οφέλους· με διάστημα 0 γίνεται επισκόπηση μία φορά. Το **Ιστορικό** εμφανίζει κάθε μέτρηση. Όταν ένα όφελος δεν χρειάζεται πλέον παρακολούθηση, επεξεργαστείτε το και επιλέξτε **Διακοπή επισκόπησης αυτού του οφέλους**.',
            'p3' => 'Όταν φτάσει μια ημερομηνία επισκόπησης το κουδούνι ειδοποιεί τον υπεύθυνο του οφέλους και τον υπεύθυνο του έργου (το Έργα - Ρυθμίσεις - Γενικά μπορεί να το περιορίσει μόνο στον υπεύθυνο του οφέλους) - **ακόμη και μετά το κλείσιμο του έργου**· ένα ακυρωμένο έργο δεν επισκοπείται. Η Επισκόπηση και η κάρτα του χαρτοφυλακίου δείχνουν τις επισκοπήσεις που εκκρεμούν, και η αναφορά **Κλεισίματος** στην καρτέλα Αναφορές περιλαμβάνει κάθε όφελος: τι έχει επιτευχθεί και τι έρχεται ακόμη.',
        ],
        'intake' => [
            'nav' => 'Προτάσεις και έγκριση',
            'title' => 'Πρόταση ενός έργου, και έγκρισή του',
            'intro' => 'Από ένα «μπορούμε να έχουμε...» σε μια φόρμα έως ένα εγκεκριμένο έργο, με την αιτιολόγησή του γραμμένη.',
            'p1' => 'Οποιαδήποτε φόρμα μπορεί να προτείνει ένα έργο. Στις **Φόρμες**, ανοίξτε τη φόρμα, μεταβείτε στο **Τι συμβαίνει στη συνέχεια** και προσθέστε **Δημιουργία πρότασης έργου** στο «Όταν υποβληθεί» (ή στο «Όταν εγκριθεί», για μια φόρμα που εγκρίνεται πρώτα). Αφήστε τα πλαίσιά της κενά και το έργο ονομάζεται από τη φόρμα και αυτόν που την έστειλε, η περίληψή του είναι οι απαντήσεις του και ανήκει στην εταιρεία του· ή συμπληρώστε τα - όνομα, γιατί χρειάζεται, εκτιμώμενο κόστος, αναμενόμενο όφελος, ημερομηνία που επιθυμείται, τρόπος λειτουργίας, προτεραιότητα, υπεύθυνος έργου - χρησιμοποιώντας τις απαντήσεις, όπως {{submission.fields.Budget}}. Η ίδια ενέργεια λειτουργεί σε οποιονδήποτε κανόνα στις **Ροές εργασιών**.',
            'p2' => 'Μια πρόταση εμφανίζει ένα πλαίσιο **Πρόταση** στην Επισκόπησή της - ποιος την πρότεινε και με ποια φόρμα, το εκτιμώμενο κόστος, το αναμενόμενο όφελος και γιατί χρειάζεται - και ένα chip και μια προβολή **Αναμονή έγκρισης** στο χαρτοφυλάκιο. Μέχρι να εγκριθεί μπορεί να μείνει Προτεινόμενη ή να ακυρωθεί, τίποτε άλλο. Ένας εγκρίνων πατά **Έγκριση** (παραμένει Προτεινόμενη ώστε να την ξεκινήσει ο υπεύθυνος του έργου της, ή ξεκινά αμέσως - ρύθμιση) ή **Απόρριψη** με αιτιολογία (ακυρώνεται· τίποτα δεν διαγράφεται). Οι εγκρίνοντες ενημερώνονται για μια νέα πρόταση από το κουδούνι· όποιος την πρότεινε ενημερώνεται για την απόφαση, και μια ροή εργασιών στο «Μια πρόταση έργου εγκρίνεται ή απορρίπτεται» μπορεί να στείλει email σε κάποιον που ρώτησε σε μια φόρμα.',
            'p3' => 'Το Έργα - Ρυθμίσεις - Γενικά αποφασίζει ποια νέα έργα χρειάζονται έγκριση (όσα προτείνονται από φόρμα - η προεπιλογή -, κάθε νέο έργο ή κανένα), ποιος εγκρίνει (όσοι διαχειρίζονται τα Έργα, ή ένα συγκεκριμένο άτομο - το Διαχείριση έργων μπορεί πάντα επίσης να αποφασίσει) και τι κάνει η έγκριση. Τα έργα που δημιουργήθηκαν πριν ενεργοποιηθεί η ρύθμιση δεν επηρεάζονται ποτέ.',
        ],
        'control' => [
            'nav' => 'Έλεγχος αλλαγών',
            'title' => 'Έλεγχος αλλαγών: baselines και αιτήματα αλλαγής',
            'intro' => 'Τι συμφωνήθηκε, πόσο έχει παρεκκλίνει το σχέδιο από τότε και ποιος συμφώνησε να μετακινηθεί.',
            'p1' => 'Μια **baseline** καταγράφει το σχέδιο όπως συμφωνήθηκε: την έναρξη και την ημερομηνία-στόχο λήξης, τον προγραμματισμένο προϋπολογισμό, τις εργασίες και τις εκτιμώμενες ώρες, τα στοιχεία Must και κάθε στάδιο, ορόσημο και γραμμή προϋπολογισμού. Η καρτέλα Έλεγχος αλλαγών (ενεργή για τα έργα σε στάδια· ενεργοποιήστε την για άλλα από τα Εργαλεία) τη συγκρίνει με το σχέδιο όπως είναι τώρα - **+17 ημέρες** στη λήξη, **+£4.950 (+20%)** στον προϋπολογισμό - και απαριθμεί τι μετακινήθηκε, στοιχείο προς στοιχείο: ένα ορόσημο δύο εβδομάδες αργότερα, μια γραμμή προϋπολογισμού που αυξήθηκε, ένα στοιχείο Must που προστέθηκε. Επιλέξτε μια παλαιότερη baseline στο **Σύγκριση με** για να μετρήσετε έναντι εκείνης. Πατήστε **Baseline** για να δημιουργήσετε μία με το χέρι, με ετικέτα αν θέλετε· μια baseline δεν επεξεργάζεται ποτέ, δημιουργείται μια νέα.',
            'p2' => 'Ένα **αίτημα αλλαγής** ζητά να μετακινηθεί το συμφωνημένο σχέδιο πριν μετακινηθεί: ποια είναι η αλλαγή, γιατί, και τι κάνει στον χρόνο (ημέρες, + αργότερα), στο κόστος (+ περισσότερο, - εξοικονόμηση) και στο πεδίο εφαρμογής. Πατήστε **Υποβολή**. Όποιος το υπέβαλε μπορεί να το επεξεργαστεί ή να το αποσύρει όσο περιμένει. Όταν **εγκριθεί**, δημιουργείται μια νέα baseline - το αλλαγμένο σχέδιο γίνεται το συμφωνημένο - και, από προεπιλογή, η ημερομηνία-στόχος λήξης μετακινείται κατά τις ημέρες του και το κόστος του γίνεται μια γραμμή προϋπολογισμού με το όνομά του. Η **Απόρριψη** καταγράφει την απόφαση και δεν αλλάζει τίποτα. Τα αιτήματα δεν διαγράφονται ποτέ: είναι το αρχείο του γιατί μετακινήθηκε το σχέδιο, και καθένα βρίσκεται στο ιστορικό. Ο υπεύθυνος του έργου ενημερώνεται για ένα αίτημα που υποβάλλει κάποιος άλλος, και ένα αίτημα που περιμένει εμφανίζεται στην Επισκόπηση και στην κάρτα του χαρτοφυλακίου.',
            'p3' => 'Το Έργα - Ρυθμίσεις - Γενικά αποφασίζει πώς λειτουργεί για εσάς: αν μια baseline δημιουργείται **αυτόματα** όταν ένα έργο γίνεται ενεργό, ή τότε **και** όταν ξεκινά κάθε στάδιο (η προεπιλογή), ή μόνο με το χέρι· **ποιος αποφασίζει** για τα αιτήματα αλλαγής - ο υπεύθυνος του έργου ή όποιος διαχειρίζεται τα Έργα (η προεπιλογή), οποιοσδήποτε στην ομάδα του έργου, ή μόνο όσοι διαχειρίζονται τα Έργα· αν το άτομο που υπέβαλε ένα αίτημα μπορεί να το **αποφασίσει** επίσης· και αν η έγκριση **μετακινεί επίσης το σχέδιο** ή δημιουργεί μόνο τη νέα baseline.',
        ],
        'announce' => [
            'nav' => 'Ανακοίνωση διακοπής',
            'title' => 'Ανακοίνωση διακοπής στην Κατάσταση υπηρεσιών',
            'intro' => '«Ημέρα μετακόμισης: τα τηλέφωνα εκτός το Σάββατο» - ενημερώνονται όλοι πριν συμβεί.',
            'p1' => 'Η καρτέλα Συνδέσεις έχει ένα πλαίσιο **Κατάσταση υπηρεσιών** για όσους μπορούν να ανοίξουν την Κατάσταση υπηρεσιών. Πατήστε **Ανακοίνωση**, δώστε έναν τίτλο, πότε ξεκινά και πότε τελειώνει, τι πρέπει να γνωρίζουν οι άνθρωποι και τις υπηρεσίες που επηρεάζονται (Συντήρηση, εκτός αν επιλέξετε άλλη επίπτωση). Από προεπιλογή γίνεται **προγραμματισμένη συντήρηση**: εμφανίζεται αμέσως ως Επερχόμενη στην Κατάσταση υπηρεσιών, γίνεται συμβάν σε αυτές τις υπηρεσίες στην έναρξή της και επιλύεται στη λήξη της. Αποσύρετέ την με το σταυρό πριν ξεκινήσει. Το πλαίσιο απαριθμεί ό,τι έχει ανακοινώσει το έργο, και τόσο η ανακοίνωση όσο και η απόσυρση καταγράφονται στο ιστορικό του έργου.',
            'p2' => 'Το **Έργα - Ρυθμίσεις - Γενικά - Ανακοίνωση διακοπής στην Κατάσταση υπηρεσιών** αποφασίζει τι κάνει η Ανακοίνωση: ως προγραμματισμένη συντήρηση (η προεπιλογή), αμέσως ως συμβάν, ή καθόλου. Η διαγραφή του έργου αφήνει στην Κατάσταση υπηρεσιών ό,τι έχει ανακοινώσει: είναι πραγματική δουλειά σε πραγματικές υπηρεσίες.',
        ],
        'reports' => [
            'nav' => 'Ενημερώσεις και αναφορές',
            'title' => 'Ο διευθυντής έργων AI: ενημερώσεις και αναφορές',
            'intro' => 'Μια ενημέρωση για το τι σας χρειάζεται αυτή την εβδομάδα, και αναφορές κατάστασης που συντάσσονται για να τις ελέγξετε.',
            'p1' => 'Μόλις ρυθμιστεί ένας πάροχος AI στο **Έργα - Ρυθμίσεις - AI**, η Επισκόπηση ενός έργου έχει ένα πλαίσιο **Ενημέρωση**. Πατήστε **Ενημερώστε με** και το AI διαβάζει το έργο - ημερομηνίες, πορεία, όρια, στάδια, εργασίες που καθυστερούν και επερχόμενες, κινδύνους και ζητήματα, τον προϋπολογισμό και τις αλλαγές της τελευταίας εβδομάδας, και από την έκδοση 3.3.0 επίσης την προτεραιότητα, τα ορόσημα, τις εκτιμήσεις, τις αποφάσεις, τα αιτήματα αλλαγής, την earned value, τα οφέλη, ποιες εργασίες περιμένουν άλλες και τη κρίσιμη διαδρομή, τα στοιχεία λίστας ελέγχου πύλης που παραμένουν ανοιχτά και τον χάρτη ενδιαφερομένων - και γράφει τέσσερα έως επτά σύντομα σημεία για το τι χρειάζεται προσοχή, με πρώτο το πιο σημαντικό. Η τελευταία ενημέρωση παραμένει στη σελίδα για όλους· μια νέα συντάσσεται το πολύ κάθε 10 λεπτά, επειδή καθεμία είναι μια κλήση προς τον πάροχο.',
            'p2' => 'Η καρτέλα **Αναφορές** περιέχει τις αναφορές highlight, εξαίρεσης, checkpoint και κλεισίματος ενός έργου. Επιλέξτε το είδος και την περίοδο και πατήστε **Σύνταξη** για να γράψει μία το AI, ή **Γράψτε** για να ξεκινήσετε τη δική σας. Όποιος μπορεί να αλλάξει το έργο μπορεί να συντάξει, να επεξεργαστεί και να διαγράψει ένα προσχέδιο. Η **Έγκριση** ανήκει στον υπεύθυνο του έργου, στο άτομο που δημιούργησε το έργο και σε όσους διαχειρίζονται τα Έργα - μια εγκεκριμένη αναφορά είναι οριστική, δεν μπορεί να επεξεργαστεί και είναι αυτή που διαβάζει το διοικητικό συμβούλιο. Κάθε αναφορά δείχνει αν τη συνέταξε το AI και αν κάποιο άτομο την έχει αλλάξει από τότε. Το **Αντιγραφή** την τοποθετεί στο πρόχειρο για επικόλληση σε ένα email ή ένα έγγραφο.',
            'p3' => 'Το AI βλέπει μόνο ό,τι μπορεί να δει το άτομο που ρωτά: τα αιτήματα, οι αλλαγές και η Κατάσταση υπηρεσιών παραλείπονται για κάποιον χωρίς αυτές τις ενότητες. Του έχει ζητηθεί να δηλώνει μόνο ό,τι υπάρχει στο έργο, και να το λέει όταν κάτι δεν είναι γνωστό - αλλά μπορεί και πάλι να κάνει λάθος, γι\' αυτό διαβάστε ένα προσχέδιο πριν το εγκρίνετε. Γράφει στη γλώσσα στην οποία χρησιμοποιείτε το FreeITSM. Το κείμενο που πληκτρολογούν οι χρήστες στο έργο μεταβιβάζεται ως δεδομένα, ποτέ ως οδηγίες.',
            'p4' => '**Αυτόματη σύνταξη αναφοράς** (στην καρτέλα Αναφορές): κάθε εβδομάδα, κάθε δύο εβδομάδες ή κάθε μήνα, όσο το έργο είναι ενεργό, μια αναφορά highlight, checkpoint ή εξαίρεσης συντάσσεται στην αρχή της περιόδου - από το AI όταν έχει ρυθμιστεί, αλλιώς με τα γεγονότα για να τη γράψετε - και ο υπεύθυνος του έργου ενημερώνεται. Γράφεται με την πρόσβαση του υπεύθυνου του έργου, επομένως περιέχει μόνο ό,τι μπορούσε να δει εκείνος. Δεν εγκρίνεται ποτέ αυτόματα. Το **Αποστολή** σε μια εγκεκριμένη αναφορά την στέλνει με email στα μέλη του έργου που επιλέγετε και σε άλλες διευθύνσεις, με προαιρετική σημείωση στην αρχή· η αναφορά δείχνει σε ποιους στάλθηκε και πότε.',
        ],
        'assistant' => [
            'nav' => 'Ρωτήστε το AI',
            'title' => 'Ρωτήστε το AI - ο βοηθός του έργου',
            'intro' => 'Μια συζήτηση για ένα έργο, με έναν διαχειριστή έργου AI που μπορεί να το διαβάσει και να προτείνει αλλαγές.',
            'p1' => 'Σε ένα έργο, το **Ρωτήστε το AI** (πάνω δεξιά) ανοίγει τον βοηθό. Διαβάζει το έργο όπως θα το διαβάζατε κι εσείς - τίποτα που δεν θα μπορούσατε να ανοίξετε μόνοι σας - και απαντά με απλά λόγια, είτε δεν έχετε διαχειριστεί ποτέ έργο είτε γνωρίζετε το PRINCE2 απέξω. Απαιτείται πάροχος AI ρυθμισμένος στα Έργα - Ρυθμίσεις - AI.',
            'p2' => 'Εντοπίζει πόσο έχει στηθεί το έργο. Ένα έργο που έχει μόνο όνομα παίρνει έναν **προπονητή**: τι αφορά, πώς φαίνεται το «ολοκληρώθηκε», περίπου πότε, ποιοι εμπλέκονται - και στη συνέχεια μια προτεινόμενη οργάνωση: ο στόχος, οι ημερομηνίες, ο τρόπος διαχείρισης, τα στάδια, οι αρχικές εργασίες, τα ορόσημα και οι πιθανοί κίνδυνοι. Ένα έργο σε εξέλιξη παίρνει βοήθεια για να **μένετε μπροστά**: τι έχει καθυστερήσει, ποιοι κίνδυνοι είναι υψηλοί, ποια ορόσημα χάθηκαν, ποια αιτήματα αλλαγής περιμένουν. Τα κουμπιά κάτω από τη συζήτηση προτείνουν μια ερώτηση για να ξεκινήσετε.',
            'p3' => '**Δεν αλλάζει ποτέ μόνο του το έργο.** Οι προτεινόμενες αλλαγές εμφανίζονται ως κάρτα - ένα πλαίσιο για καθεμία, όλα επιλεγμένα - με **Εφαρμογή** και **Απόρριψη**. Η Εφαρμογή κάνει τις επιλεγμένες ακριβώς σαν να τις είχατε κάνει εσείς στις οθόνες, με τα δικά σας δικαιώματα, και εμφανίζονται στο Ιστορικό ως δικές σας. Αν δεν επιτρέπεται να αλλάξετε το έργο, σας δίνει μόνο συμβουλές.',
            'p4' => '**Θυμάται.** Η συζήτησή σας σε ένα έργο διατηρείται και τα παλαιότερα μέρη συμπτύσσονται σε μια σύντομη μνήμη, ώστε να συνεχίζετε από εκεί που μείνατε· μετά από απουσία, ανοίγει με όσα άλλαξαν από τότε. Η **Επανεκκίνηση** τη σβήνει. Η επιλογή Έργα - Ρυθμίσεις - Γενικά - *Μνήμη του βοηθού AI* την κάνει μία συζήτηση που μοιράζεται όλη η ομάδα του έργου, αντί για μία ανά άτομο.',
        ],
        'companies' => [
            'nav' => 'Εταιρείες',
            'title' => 'Έργα και εταιρείες',
            'intro' => 'Κάθε έργο ανήκει σε μία εταιρεία.',
            'p1' => 'Σε μια εγκατάσταση με περισσότερες από μία εταιρείες, ένα έργο ανήκει στην εταιρεία όπου δημιουργήθηκε (ή σε αυτήν που θα επιλέξετε) και οι εργασίες του ανήκουν επίσης εκεί. Βλέπετε μόνο τα έργα των εταιρειών που μπορείτε να δείτε, και η προβολή Όλες οι εταιρείες τα εμφανίζει μαζί. Μια εργασία από άλλη εταιρεία δεν μπορεί να μπει σε έργο.',
        ],
        'settings' => [
            'nav' => 'Ρυθμίσεις',
            'title' => 'Ρυθμίσεις και δικαιώματα',
            'intro' => 'Ποιος μπορεί να δημιουργεί, να αλλάζει και να διαγράφει έργα, και οι όροι και τα όρια που χρησιμοποιεί η ενότητα.',
            'p1' => 'Τα **Έργα - Ρυθμίσεις** έχουν επτά καρτέλες και καθεμία χρειάζεται δικό της δικαίωμα, που δίνεται στο **Σύστημα - Ρόλοι**· το Διαχείριση έργων τις καλύπτει και τις επτά. Όποιος δεν έχει καμία βλέπει μια σελίδα που λέει ότι δεν υπάρχει τίποτα προς ρύθμιση.',
            'general_d' => 'Ο τρόπος με τον οποίο εκτελείται ένα νέο έργο, αν δεν επιλέξετε άλλον, ποιος μπορεί να δημιουργεί έργα, ποιος μπορεί να αλλάζει ένα, ποιες ημερομηνίες μπαίνουν στο Ημερολόγιο και πώς ανακοινώνεται η διακοπή υπηρεσίας στην Κατάσταση υπηρεσιών. Επίσης οι όροι προτεραιότητας, η αρχική σειρά του χαρτοφυλακίου, τι μετρά το burn-up, ο έλεγχος αλλαγών (αυτόματα baselines, ποιος αποφασίζει, απόφαση για τις δικές σας αλλαγές, τι κάνει η έγκριση), η Εργαλειοθήκη στην Επισκόπηση (ενεργή), η μνήμη του βοηθού AI (ξεχωριστή για κάθε άτομο), αν αποστέλλονται email στους εξωτερικούς συνεργάτες (όχι), η περιοδική σύνοψη εκπρόθεσμων εργασιών (εβδομαδιαία) και οι υπενθυμίσεις (μετά από 3 ημέρες), ποιος μπορεί να βλέπει ένα νέο έργο (όλοι με πρόσβαση στα Έργα), αν ένα ανοιχτό στοιχείο της λίστας ελέγχου της πύλης σταματά ένα «προχωρήστε» (ναι), κάθε πότε εξετάζονται τα οφέλη (κάθε 3 μήνες) και ποιος ειδοποιείται, και ποιες προτάσεις χρειάζονται έγκριση, ποιος τις εγκρίνει και τι κάνει η έγκριση.',
            'health_d' => 'Πότε ένα ενεργό έργο γίνεται πορτοκαλί ή κόκκινο: πόσο κοντά είναι ο στόχος, πόση δουλειά πρέπει να έχει γίνει μέχρι τότε, πόση εκπρόθεσμη εργασία το κάνει κόκκινο και πόσα νέα συσχετισμένα αιτήματα το κάνουν πορτοκαλί· τι προκαλεί ένα χαμένο ορόσημο ή μια εξάρτηση ή απόφαση που πέρασε την ημερομηνία της (εξ ορισμού πορτοκαλί)· και οι ώρες της σελίδας Δυναμικότητα ανά εβδομάδα, το επίπεδο πίεσης, τα πολλά έργα, οι εργάσιμες ημέρες και αν μετρούν οι βάρδιες του προγράμματος βαρδιών.',
            'roles_d' => 'Οι ρόλοι που προσφέρονται στην καρτέλα Άτομα ενός έργου. Σύρετε για αλλαγή σειράς· καταργήστε την επιλογή Προσφέρεται στα έργα για να σταματήσει η προσφορά ενός ρόλου· η διαγραφή ενός αφήνει όσους τον έχουν στα έργα τους χωρίς ρόλο.',
            'raid_d' => 'Οι πέντε όροι για τα βήματα της κλίμακας πιθανότητας και της κλίμακας επίπτωσης, από το χαμηλότερο.',
            'ai_d' => 'Ο πάροχος AI, το μοντέλο και το κλειδί που χρησιμοποιούν οι ενημερωτικές αναφορές και οι αναφορές που συντάσσονται αυτόματα. Το κλειδί ξοδεύει χρήματα του οργανισμού σας, γι\' αυτό έχει δικό του δικαίωμα.',
            'budget_d' => 'Το νόμισμα για τα νέα έργα, αν ένα έργο μπορεί να επιλέξει δικό του, πώς κοστολογείται ο χρόνος που καταγράφεται, και οι ωριαίες χρεώσεις - η προεπιλεγμένη και του κάθε τεχνικού - καθεμία από μια ημερομηνία. Επίσης αν η Επιτρεπόμενη υπέρβαση μετρά όσα έχουν δαπανηθεί (εξ ορισμού) ή την πρόβλεψη, και αν οι ώρες που εκτιμώνται ακόμη στις ανοιχτές εργασίες μετρούν στην πρόβλεψη (μετρούν).',
            'templates_d' => 'Τα πρότυπα που προσφέρονται για νέα έργα: απόκρυψη ενός ενσωματωμένου, και μετονομασία, απενεργοποίηση ή διαγραφή όσων αποθηκεύτηκαν από ένα έργο. Το ίδιο δικαίωμα επιτρέπει σε κάποιον να αποθηκεύσει ένα έργο ως πρότυπο.',
            'p2' => 'Το **Ποιος μπορεί να δημιουργεί έργα** είναι είτε οποιοσδήποτε μπορεί να ανοίξει τα Έργα (η προεπιλογή) είτε μόνο όσοι διαχειρίζονται τα Έργα. Το **Ποιος μπορεί να αλλάζει ένα έργο** είναι είτε η ομάδα του (η προεπιλογή) είτε οποιοσδήποτε μπορεί να ανοίξει τα Έργα. Η ομάδα ενός έργου είναι ο διαχειριστής του έργου, ο δημιουργός του και τα μέλη του, συμπεριλαμβανομένων των τεχνικών μιας ομάδας που είναι μέλος. Όσοι διαχειρίζονται τα Έργα, και οι διαχειριστές, μπορούν πάντα να αλλάζουν οποιοδήποτε έργο.',
            'p3' => 'Η **διαγραφή** ενός έργου περιορίζεται πάντα στον διαχειριστή του έργου, στον δημιουργό του και σε όσους διαχειρίζονται τα Έργα, ανεξάρτητα από τις ρυθμίσεις. Όταν δεν επιτρέπεται να αλλάξετε ένα έργο, η σελίδα του κρύβει τα κουμπιά που θα το έκαναν, και ο διακομιστής απορρίπτει την αλλαγή ούτως ή άλλως.',
