            'p1' => 'Τα Έργα μπορούν να διαβαστούν και να αλλαχθούν μέσω του REST API, και να διαβαστούν από βοηθό AI μέσω του διακομιστή MCP. Και τα δύο ρυθμίζονται στο **Σύστημα - API**, και ένα κλειδί API φτάνει πάντα μόνο στις εταιρείες που μπορεί να δει ο τεχνικός του.',
            'p2' => 'Στο **War Room**, ο Warbot απαντά και σε ερωτήσεις για τα έργα - «ποια έργα βγαίνουν εκτός πλάνου;», «κάνει κάποιο έργο κάτι μεγάλο αυτή την εβδομάδα;» - ή χρησιμοποιήστε τα **/projects**, **/project** και **/dates**. Προσφέρεται μόνο σε όσους μπορούν να ανοίξουν τα Έργα, απαντά για τα έργα που μπορούν να δουν, και δεν αναφέρει ποτέ χρήματα: όλοι στο κανάλι διαβάζουν τις απαντήσεις του.',
